WITH filtered AS (SELECT *, CONCAT(dept_name, ' - ', location) AS dept_name_location, COALESCE(location, 'DIRECT') AS location_clean FROM departments WHERE dept_name IS NOT NULL) SELECT id, dept_name, location, budget, dept_name_location, location_clean, SUM(budget) OVER (PARTITION BY location, dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget, FIRST_VALUE(location) IGNORE NULLS OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_location FROM filtered;
